import csv, json, os

desc_path = '/root/data/stock-descriptions.csv'
hist_dir = '/root/data/indiv-stock'

stocks = []

with open(desc_path, newline='', encoding='utf-8') as f:
    r = csv.DictReader(f)
    for row in r:
        ticker = (row.get('ticker') or '').strip()
        sector = (row.get('sector') or '').strip()
        name = (row.get('full name') or '').strip()
        mc_raw = (row.get('marketCap') or '').strip()
        market_cap = None
        if mc_raw and mc_raw.lower() != 'nan':
            try:
                market_cap = float(mc_raw)
            except ValueError:
                market_cap = None

        stocks.append({
            'ticker': ticker,
            'sector': sector,
            'name': name,
            'marketCap': market_cap,
        })

# derive simple metrics from price histories (uses /root/data/indiv-stock)
metrics = {}
for s in stocks:
    t = s['ticker']
    p = os.path.join(hist_dir, f'{t}.csv')
    if not os.path.exists(p):
        continue
    with open(p, newline='', encoding='utf-8') as f:
        rr = csv.DictReader(f)
        first = None
        last = None
        for row in rr:
            if not first:
                first = row
            last = row
    if not last:
        continue
    def fnum(x):
        try:
            return float(x)
        except Exception:
            return None
    first_close = fnum((first or {}).get('Close'))
    last_close = fnum(last.get('Close'))
    last_date = (last.get('Date') or '').strip()
    ret = None
    if first_close and last_close and first_close != 0:
        ret = (last_close / first_close) - 1.0

    metrics[t] = {
        'latestClose': last_close,
        'latestDate': last_date,
        'periodReturn': ret,
    }

