  const bubbleEl = document.getElementById('bubbleChart');
  const infoEl = document.getElementById('selectionInfo');
  const tooltip = d3.select('#tooltip');

  const width = 680;
  const height = 560;

  const sectors = Array.from(new Set(STOCKS.map(d => d.sector))).sort(d3.ascending);
  const color = d3.scaleOrdinal(sectors, d3.schemeTableau10);

  const marketCaps = STOCKS.map(d => d.marketCap).filter(v => typeof v === 'number' && isFinite(v));
  const rScale = d3.scaleSqrt()
    .domain(d3.extent(marketCaps))
    .range([12, 52]);

  const etfRadius = 18;

  function hash32(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  }

  function mulberry32(a) {
    return function() {
      let t = a += 0x6D2B79F5;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function formatMarketCap(v) {
    if (typeof v !== 'number' || !isFinite(v)) return '—';

    const abs = Math.abs(v);
    const trim = (s) => s.replace(/\.00$/, '').replace(/(\.\d)0$/, '$1');

    if (abs >= 1e12) return trim(d3.format('.2f')(v / 1e12)) + 'T';
    if (abs >= 1e9) return trim(d3.format('.2f')(v / 1e9)) + 'B';
    if (abs >= 1e6) return trim(d3.format('.2f')(v / 1e6)) + 'M';
    return d3.format(',')(v);
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  // Cluster centers (kept close to each other and centered)
  const centerRadius = 120;
  const sectorCenters = new Map();
  sectors.forEach((s, i) => {
    const ang = (2 * Math.PI * i) / sectors.length - Math.PI / 2;
    sectorCenters.set(s, {
      x: width / 2 + centerRadius * Math.cos(ang),
      y: height / 2 + centerRadius * Math.sin(ang)
    });
  });

  const nodes = STOCKS.map(d => {
    const isETF = d.sector === 'ETF' || d.marketCap == null || !isFinite(d.marketCap);
    const r = isETF ? etfRadius : rScale(d.marketCap);

    const c = sectorCenters.get(d.sector) || { x: width / 2, y: height / 2 };
    const rand = mulberry32(hash32(d.ticker));

    return {
      ...d,
      isETF,
      r,
      x: c.x + (rand() - 0.5) * 60,
      y: c.y + (rand() - 0.5) * 60
    };
  });

  const svg = d3.select(bubbleEl)
    .append('svg')
    .attr('viewBox', `0 0 ${width} ${height}`)
    .attr('width', '100%')
    .attr('height', '100%');

  // Legend
  const legend = svg.append('g')
    .attr('transform', 'translate(14, 14)');

  const legendItems = legend.selectAll('g.item')
    .data(sectors)
    .join('g')
    .attr('class', 'item')
    .attr('transform', (d, i) => `translate(0, ${i * 18})`);

  legendItems.append('rect')
    .attr('width', 12)
    .attr('height', 12)
    .attr('rx', 3)
    .attr('fill', d => color(d))
    .attr('stroke', 'rgba(0,0,0,0.35)');

  legendItems.append('text')
    .attr('x', 18)
    .attr('y', 10)
    .attr('fill', 'rgba(232,236,255,0.88)')
    .attr('font-size', 12)
    .text(d => d);

  const g = svg.append('g');

  const circles = g.selectAll('circle')
    .data(nodes, d => d.ticker)
    .join('circle')
    .attr('r', d => d.r)
    .attr('fill', d => color(d.sector))
    .attr('stroke', 'rgba(0,0,0,0.5)')
    .attr('stroke-width', 1)
    .style('cursor', 'pointer');

  const labels = g.selectAll('text.ticker')
    .data(nodes, d => d.ticker)
    .join('text')
    .attr('class', 'ticker')
    .attr('text-anchor', 'middle')
    .attr('dominant-baseline', 'middle')
    .attr('fill', 'rgba(255,255,255,0.92)')
    .attr('font-weight', 700)
    .attr('pointer-events', 'none')
    .attr('font-size', d => Math.max(9, Math.min(13, d.r * 0.55)))
    .text(d => d.ticker);

  let selectedTicker = null;

  function setSelected(ticker) {
    selectedTicker = ticker;

    circles
      .attr('stroke-width', d => (d.ticker === selectedTicker ? 3 : 1))
      .attr('stroke', d => (d.ticker === selectedTicker ? 'rgba(255, 209, 102, 0.95)' : 'rgba(0,0,0,0.5)'));

    tableRows.classed('selected', d => d.ticker === selectedTicker);

    if (!selectedTicker) {
      infoEl.textContent = 'Click a bubble or row to see details.';
      return;
    }

    const s = STOCKS.find(d => d.ticker === selectedTicker);
    const m = STOCK_METRICS[selectedTicker] || {};

    const price = (typeof m.latestClose === 'number' && isFinite(m.latestClose))
      ? `$${d3.format(',.2f')(m.latestClose)} (${m.latestDate || 'n/a'})`
      : '—';

    const ret = (typeof m.periodReturn === 'number' && isFinite(m.periodReturn))
      ? (d3.format('+.1%')(m.periodReturn))
      : '—';

    infoEl.innerHTML = `
      <div><strong>${escapeHtml(s.ticker)}</strong> — ${escapeHtml(s.name)} (${escapeHtml(s.sector)})</div>
      <div style="color: rgba(232,236,255,0.72); margin-top: 4px;">
        Market cap: <span style="color: rgba(232,236,255,0.9);">${escapeHtml(formatMarketCap(s.marketCap))}</span>
        &nbsp;|&nbsp; Latest close (from price history): <span style="color: rgba(232,236,255,0.9);">${escapeHtml(price)}</span>
        &nbsp;|&nbsp; Period return: <span style="color: rgba(232,236,255,0.9);">${escapeHtml(ret)}</span>
      </div>
    `;

    // Scroll row into view (if needed)
    const tr = document.querySelector(`tr[data-ticker="${CSS.escape(selectedTicker)}"]`);
    if (tr) tr.scrollIntoView({ block: 'nearest' });
  }

  function clearSelected() {
    setSelected(null);
  }

  // Tooltip interactions (non-ETF only)
  circles
    .on('mouseover', (event, d) => {
      if (d.isETF) return;
      tooltip
        .style('opacity', 1)
        .html(
          `<div class="tt-ticker">${escapeHtml(d.ticker)}</div>` +
          `<div class="tt-name">${escapeHtml(d.name)}</div>` +
          `<div class="tt-sector">Sector: ${escapeHtml(d.sector)}</div>`
        );
    })
    .on('mousemove', (event, d) => {
      if (d.isETF) return;
      tooltip
        .style('left', (event.pageX + 12) + 'px')
        .style('top', (event.pageY + 12) + 'px');
    })
    .on('mouseout', (event, d) => {
      if (d.isETF) return;
      tooltip.style('opacity', 0);
    })
    .on('click', (event, d) => {
      event.stopPropagation();
      setSelected(d.ticker);
    });

  // Click empty chart area to clear selection
  svg.on('click', () => clearSelected());

  // Table
  const tbody = d3.select('#stockTable tbody');

  const tableRows = tbody.selectAll('tr')
    .data(STOCKS, d => d.ticker)
    .join('tr')
    .attr('data-ticker', d => d.ticker)
    .style('cursor', 'pointer')
    .on('click', (event, d) => {
      event.stopPropagation();
      setSelected(d.ticker);
    });

  tableRows.append('td').text(d => d.ticker);
  tableRows.append('td').text(d => d.name);
  tableRows.append('td').text(d => d.sector);
  tableRows.append('td')
    .attr('class', 'num')
    .text(d => formatMarketCap(d.marketCap));

  // Force simulation
  const simulation = d3.forceSimulation(nodes)
    .force('x', d3.forceX(d => (sectorCenters.get(d.sector) || { x: width / 2 }).x).strength(0.22))
