        d.x = Math.max(d.r + 6, Math.min(width - d.r - 6, d.x));
        d.y = Math.max(d.r + 6, Math.min(height - d.r - 6, d.y));
      }

      circles
        .attr('cx', d => d.x)
        .attr('cy', d => d.y);

      labels
        .attr('x', d => d.x)
        .attr('y', d => d.y);
    });

  // Start with no selection
  setSelected(null);
})();
